// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        uint256 balBefore = address(c).balance;

        vm.prank(depositor);
        c.withdrawAll();

        uint256 balAfter = address(c).balance;

        assertTrue(balBefore == balAfter + amount);
    }
}
